cd /workspace && python3 - <<'PY'
import json, random, sys, time
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/dev')
import ref as refmod
from adapter import execute_batch
def make(seed, n=8000):
    rng = random.Random(seed)
    U = 1 << 22; M = 3; L = 2; R = 4
    borders = [0] + sorted(rng.sample(range(1, U), R-1)) + [U]
    kind = rng.choice(['fifo','sff','wfq'])
    flows = list(range(3))
    policy = ({'kind':'wfq','weights':[[f, rng.randint(1,1024)] for f in flows]} if kind=='wfq' else {'kind':kind})
    ev=[]; nid=0; saved=[]
    while len(ev) < n:
        pick = rng.random()
        if pick < 0.62:
            ev.append(['enqueue', nid, rng.choice(flows), rng.randint(1,400), rng.randrange(U)]); nid+=1
        elif pick < 0.70:
            ev.append(['dequeue', rng.randint(1,8)])
        elif pick < 0.74: ev.append(['sample'])
        elif pick < 0.78: ev.append(['cancel', rng.randrange(0, nid+5)])
        elif pick < 0.82: ev.append(['inspect', rng.randrange(0, nid+5)])
        elif pick < 0.92:
            name = rng.randrange(4); ev.append(['save', name]); saved.append(name)
        elif saved: ev.append(['restore', rng.choice(saved)])
    return {'runs':[{'banks':M,'load_balancers':L,'fifo_bytes':10**9,'pifo_bytes':10**9,
                     'refill_batch':16,'sample_period':rng.choice([3,100]),'borders':borders,
                     'policy':policy,'events':ev}]}
bad=0
for seed in range(0, 6):
    req = make(seed)
    t=time.time(); mine=json.loads(json.dumps(execute_batch(req))); dt=time.time()-t
    t=time.time(); theirs=json.loads(json.dumps(refmod.run_batch(req))); dt2=time.time()-t
    ok = mine==theirs
    bad += 0 if ok else 1
    print('seed',seed,'engine %.2fs ref %.2fs'%(dt,dt2), 'ok' if ok else 'MISMATCH')
    if not ok:
        a,b=mine['runs'][0],theirs['runs'][0]
        for j in range(min(len(a['log']),len(b['log']))):
            if a['log'][j]!=b['log'][j]: print(' row',j,a['log'][j],b['log'][j]); break
        else:
            print(' A',json.dumps(a['state'])[:600]); print(' B',json.dumps(b['state'])[:600])
        json.dump(req, open('/workspace/dev/fail_big_%d.json'%seed,'w'))
print('big failures', bad)
PY
